code.perPoint:
c=i*pi*2; bn=bnot(bn); a=if(above(i,.5),bn*v,0); dm=.9;
xp=dm*if(below(a,v),a-1,1); yp=dm*cos(c*pi);
x=if(above(getspec(.1,0,2),.2),xp,yp);
y=if(above(getspec(.1,0,2),.2),yp,xp);

col=if(a*2%2,2,0);

redA=v*a*1.25;
greenA=0;
blueA=sin(i*20*pfx)*.3;

redB=if(above(bc,inc),v*a,redA);
greenB=if(above(bc,inc),col*.15,greenA);
blueB=if(above(bc,inc),col*.15,blueA);

redC=if(above(bc,inc*2),col*.1,redB);
greenC=if(above(bc,inc*2),col,greenB);
blueC=if(above(bc,inc*2),0,blueB);

redD=if(above(bc,inc*3),col*.1,redC);
greenD=if(above(bc,inc*3),col*.3,greenC);
blueD=if(above(bc,inc*3),cos(i*20*pfx)*.3,blueC);

redE=if(above(bc,inc*4),a,redD);
greenE=if(above(bc,inc*4),a,greenD);
blueE=if(above(bc,inc*4),v*.5,blueD);

redF=if(above(bc,inc*5),a+v,redE);
greenF=if(above(bc,inc*5),0,greenE);
blueF=if(above(bc,inc*5),a*col*.7,blueE);

red=if(above(bc,inc*6),v,redF);
green=if(above(bc,inc*6),v,greenF);
blue=if(above(bc,inc*6),v,blueF);

px=-abs(x);
py=-y/.8+px+.25-sin(pfx)*.2;
x1=px*rs-py*rc;
y1=px*rc+py*rs;
z1=sqrt(x1*x1+y1*y1)+(1-cos(sin(pfx))*.7);
x=x1/z1+(sin(cos(pfx)*.2));
y=.9/z1+(sin(cos(pfy)*.2));
